'use strict';
// GPI — Gold Pressure Imbalance. Research-only fast lab.
// Idea: enter before breakout when directional progress is efficient, closes dominate,
// counter-pressure is weak, but total displacement has not yet become an exhausted chase.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function atr(){let z=Array(N).fill(NaN);for(let i=14;i<N;i++){let s=0;for(let j=i-13;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));z[i]=s/14}return z}const A=atr();
function sig(i,q){if(i<q.bars+20||!A[i])return;let a=i-q.bars+1,up=0,dn=0,sumAbs=0,bull=0,bear=0,closeScore=0;for(let j=a;j<=i;j++){let d=M[j].c-M[j].o;sumAbs+=Math.abs(d);if(d>0){up+=d;bull++}else if(d<0){dn+=-d;bear++}let r=M[j].h-M[j].l;if(r>0)closeScore+=((M[j].c-M[j].l)/r-.5)*2}let net=M[i].c-M[a].o,eff=sumAbs?Math.abs(net)/sumAbs:0,disp=Math.abs(net)/A[i],dom=(Math.max(up,dn)+1e-9)/(Math.min(up,dn)+1e-9),cs=closeScore/q.bars;if(eff<q.eff||dom<q.dom||disp<q.minDisp||disp>q.maxDisp)return;if(net>0&&bull>=q.agree&&cs>=q.close)return'BUY';if(net<0&&bear>=q.agree&&cs<=-q.close)return'SELL'}
function run(q,L,H){let T=[],o=null;for(let i=Math.max(100,L);i<Math.min(H,N-1);i++){if(o){let b=M[i],p=null;if(o.s==='BUY'){if(b.l<=o.sl)p=o.sl;else if(b.h>=o.tp)p=o.tp}else{if(b.h>=o.sl)p=o.sl;else if(b.l<=o.tp)p=o.tp}if(p==null&&i-o.e+1>=q.hold)p=b.c;if(p!=null){T.push(o.s==='BUY'?(p-o.en)/(o.en-o.sl):(o.en-p)/(o.sl-o.en));o=null}continue}let s=sig(i,q);if(!s)continue;let en=M[i+1].o,r=q.sl*A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+q.rr*r:en-q.rr*r,e:i+1}}return T}function st(t){let w=0,g=0,l=0,e=0,p=0,d=0;for(let r of t){e+=r;if(r>0){w++;g+=r}else l-=r;p=Math.max(p,e);d=Math.max(d,p-e)}return{n:t.length,wr:t.length?100*w/t.length:0,pf:l?g/l:g?99:0,net:e,dd:d}}
let Q=[];for(let bars of [3,4,5])for(let eff of [.45,.6])for(let dom of [1.5,2])for(let minDisp of [.35,.6])for(let maxDisp of [1.2,1.6])for(let close of [.1,.25])for(let rr of [1,1.5]){let agree=Math.ceil(bars*.67);Q.push({bars,eff,dom,minDisp,maxDisp,close,agree,rr,sl:1,hold:10})}
console.log(`GPI FAST LAB | configs=${Q.length} | M5=${N} | DEV75/HOLD25`);let X=Q.map(q=>({q,d:st(run(q,0,C))})).filter(x=>x.d.n>=40).sort((a,b)=>b.d.net-a.d.net);console.log('\nTOP 25 DEV -> UNTOUCHED HOLD');X.slice(0,25).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)});console.log('\nROBUST: DEV/HOLD PF>=1.25 + positive');let Z=X.map(x=>({x,h:st(run(x.q,C,N))})).filter(z=>z.x.d.pf>=1.25&&z.x.d.net>0&&z.h.n>=15&&z.h.pf>=1.25&&z.h.net>0);if(!Z.length)console.log('NONE — reject GPI V1 and move to a different market mechanism.');else Z.slice(0,15).forEach((z,k)=>console.log(`${k+1} ${JSON.stringify(z.x.q)} | DEV T${z.x.d.n} WR${z.x.d.wr.toFixed(1)} PF${z.x.d.pf.toFixed(2)} N${z.x.d.net.toFixed(2)} DD${z.x.d.dd.toFixed(2)} | HOLD T${z.h.n} WR${z.h.wr.toFixed(1)} PF${z.h.pf.toFixed(2)} N${z.h.net.toFixed(2)} DD${z.h.dd.toFixed(2)}`));